#include <linux/slab.h>
#include <linux/uaccess.h>

int get_rfcomm_devices(void __user *arg) {
    int num_devices = 0;
    int ret = 0;
    struct rfcomm_dev *dev;
    struct rfcomm_dev_list *list = NULL;

    if (get_user(num_devices, (int __user *)arg)) {
        return -EFAULT;
    }

    if (num_devices <= 0) {
        return -EINVAL;
    }

    list = kmalloc(sizeof(*list) + num_devices * sizeof(list->devices[0]), GFP_KERNEL);
    if (!list) {
        return -ENOMEM;
    }

    list->count = 0;

    mutex_lock(&rfcomm_dev_list_lock);

    list_for_each_entry(dev, &rfcomm_dev_list, list) {
        if (list->count >= num_devices) {
            break;
        }

        if (!dev->released) {
            list->devices[list->count++] = *dev;
        }
    }

    mutex_unlock(&rfcomm_dev_list_lock);

    if (copy_to_user(arg, list, sizeof(*list) + list->count * sizeof(list->devices[0]))) {
        ret = -EFAULT;
    }

    kfree(list);
    return ret;
}
